function species(id){return SPECIES.find(s=>s.id===id)}function typeMultiplier(attack,defense){const strong={Water:['Fire'],Fire:['Grass'],Grass:['Water'],Electric:['Water','Wind'],Rock:['Electric','Fire'],Wind:['Grass']};if((strong[attack]||[]).includes(defense))return 1.55;if((strong[defense]||[]).includes(attack))return .72;return 1}
function updateHUD(){ $('#hpText').textContent=`${state.hp} / 20`;$('#hpBar').style.width=`${Math.max(0,state.hp/20*100)}%`;$('#energyText').textContent=state.energy;$('#stoneText').textContent=state.stones;$('#waveText').textContent=`${state.wave} / ${MAX_WAVE}`;$('#enemyText').textContent=state.phase==='running'?`${state.enemies.length+state.spawnLeft} wild nearby`:state.phase==='prep'?'Grove is quiet':state.phase==='victory'?'Trail defended':'Defenders needed';$('#phaseTag').textContent=state.phase==='running'?'WAVE LIVE':state.phase==='victory'?'COMPLETE':state.phase==='defeat'?'RETREAT':'PREPARE';$('#waveBtn').textContent=state.wave>=MAX_WAVE?'✦ All waves cleared':`▶ Start wave ${state.wave+1}`;$('#waveBtn').disabled=state.phase==='running'||state.phase==='victory'||state.phase==='defeat';$('#pauseBtn').disabled=state.phase!=='running';$('#statusText').textContent=state.phase==='running'?'Watch your companions defend the trail':'Place defenders along the trail';$('#mapName').textContent=mapData().name;$('#mapSub').textContent=mapData().sub;$('#mapSelect').value=state.map;$('#rosterCount').textContent=`${state.owned.length} species`}
function buildRoster(){const root=$('#roster');root.innerHTML='';state.owned.forEach(id=>{const s=species(id),n=state.towers.filter(t=>t.id===id).length;const b=document.createElement('button');b.className='creature-card'+(selectedSpecies===id?' active':'');b.innerHTML=`<div class="card-top"><div class="creature-icon" style="background:${s.color}33">${s.emoji}</div><div><div class="creature-name">${s.name}</div><div class="creature-type">${s.type} · ${s.ability}</div></div></div><div class="card-bottom"><span>⚔ ${s.damage} · ◉ ${s.range.toFixed(1)}</span><span>✧ ${s.cost}</span></div><span class="qty">${n?`×${n}`:''}</span>`;b.onclick=()=>{selectedSpecies=selectedSpecies===id?null:id;selectedTower=null;renderAll()};root.appendChild(b)})}
function updateSelection(){const el=$('#selectionInfo');if(selectedTower){const t=selectedTower,s=species(t.id),d=stageStats(t);el.innerHTML=`<div class="selected-title">${s.emoji} ${s.evo[t.stage-1]} <span class="badge">Stage ${t.stage}</span></div><div class="selected-desc">${s.type} · ${s.desc}<br>Damage ${Math.round(d.damage)} · Range ${d.range.toFixed(1)} · ${d.rate.toFixed(1)}s</div><div class="selected-actions"><button class="action-btn lime" id="evolveBtn" ${t.stage>=3?'disabled':''}>⬆ Evolve · ${t.stage===1?'1':'2'} stone</button><button class="action-btn muted" id="upgradeBtn">Power up · ${35+t.stage*20}</button><button class="action-btn danger" id="sellBtn">Sell +${Math.round(s.cost*.55)}</button></div>`;$('#evolveBtn').onclick=e=>{e.stopPropagation();evolve(t)};$('#upgradeBtn').onclick=e=>{e.stopPropagation();powerUp(t)};$('#sellBtn').onclick=e=>{e.stopPropagation();sell(t)}}else if(selectedSpecies){const s=species(selectedSpecies);el.innerHTML=`<div class="selected-title">${s.emoji} ${s.name} <span class="badge">${s.type}</span></div><div class="selected-desc">${s.desc}. Damage ${s.damage} · Range ${s.range.toFixed(1)} · Attack ${s.rate.toFixed(1)}s. Place for ✧ ${s.cost}.</div><div class="selected-actions"><button class="action-btn muted" id="cancelSelect">Cancel selection</button></div>`;$('#cancelSelect').onclick=()=>{selectedSpecies=null;renderAll()}}else{el.innerHTML='<div class="selected-title">Your grove awaits</div><div class="selected-desc">Select a companion, then place them beside the winding path.</div>'}}
function renderAll(){buildRoster();updateSelection();updateHUD();draw()}
function canPlace(x,y){return x>=0&&y>=0&&x<COLS&&y<ROWS&&!pathSet().has(tileKey(x,y))&&!state.towers.some(t=>t.x===x&&t.y===y)}
function stageStats(t){const s=species(t.id),f=[1,1.65,2.55][t.stage-1]*(1+(t.power||0)*.18);return {damage:s.damage*f*(1+state.boost*.1),range:s.range+[0,.25,.5][t.stage-1],rate:s.rate*Math.max(.65,1-(t.power||0)*.035)}}
function place(x,y){if(!selectedSpecies){const t=state.towers.find(a=>a.x===x&&a.y===y);if(t){selectedTower=t;selectedSpecies=null;renderAll()}return}if(!canPlace(x,y)){say('That tile is too wild to settle.');return}const s=species(selectedSpecies);if(state.energy<s.cost){say('Not enough energy yet!');return}state.energy-=s.cost;const t={x,y,id:selectedSpecies,stage:1,power:0,cool:0};state.towers.push(t);selectedTower=t;selectedSpecies=null;spark(center(x,y).x,center(x,y).y,s.color,9);renderAll();save()}
