function powerUp(t){const cost=35+t.stage*20;if(state.energy<cost)return say('Not enough energy to power up.');state.energy-=cost;t.power=(t.power||0)+1;say('Companion powered up!');renderAll();save()}
function sell(t){state.energy+=Math.round(species(t.id).cost*.55);state.towers=state.towers.filter(a=>a!==t);selectedTower=null;renderAll();save()}
