function say(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function spark(x,y,color,n=6){for(let i=0;i<n;i++)state.particles.push({x,y,vx:(Math.random()-.5)*95,vy:(Math.random()-.5)*95,life:.45+Math.random()*.35,max:.8,size:2+Math.random()*3,color})}
function floatText(x,y,text,color='#fff'){state.floats.push({x,y,text,color,life:1.05})}

