function floatText(x,y,text,color='#fff'){state.floats.push({x,y,text,color,life:1.05})}
function startWave(){if(state.phase!=='prep'||state.wave>=MAX_WAVE)return;state.wave++;state.phase='running';state.spawnLeft=5+Math.floor(state.wave*1.35);if(state.wave%10===0)state.spawnLeft+=1;state.spawnTimer=.25;state.elapsed=0;selectedSpecies=null;selectedTower=null;renderAll();save()}
$('#waveBtn').onclick=startWave;$('#pauseBtn').onclick=()=>{paused=!paused;$('#pauseBtn').textContent=paused?'▶ Resume':'Ⅱ Pause'};$('#speedBtn').onclick=()=>{speed=speed===1?2:1;$('#speedBtn').textContent=`${speed}× Speed`};
function makeEnemy(){const wave=state.wave,boss=wave%10===0&&state.spawnLeft===1;let kinds=['normal','normal','fast','tank','flying'];let kind=boss?'boss':kinds[Math.floor(Math.random()*Math.min(kinds.length,2+Math.floor(wave/4)))];let colors=Object.values(TYPES),element=['Fire','Water','Grass','Electric','Rock','Wind'][Math.floor(Math.random()*6)];let maxHp=(18+wave*8)*mapData().difficulty*(kind==='tank'?2.15:kind==='boss'?12:kind==='fast'?.68:kind==='flying'?.85:1);if(boss)kind='boss';const first=pathCells()[0],p=center(...first);return {kind,element,color:kind==='boss'?'#9d5d9c':kind==='tank'?'#9b795f':kind==='fast'?'#e98c69':kind==='flying'?'#9b9de1':colors[Math.floor(Math.random()*colors.length)],maxHp,hp:maxHp,progress:0,x:p.x,y:p.y,speed:(kind==='fast'?1.5:kind==='boss'?.48:kind==='tank'?.52:kind==='flying'?1.08:.82)*(1+wave*.012),reward:kind==='boss'?45:kind==='tank'?12:8,slow:0,poison:0,stun:0,burn:0}}
